 	crashing_cpu = safe_smp_processor_id();

@@ -867,7 +896,17 @@ void nmi_shootdown_cpus(nmi_shootdown_cb callback)
 		msecs--;
 	}

-	/* Leave the nmi callback set */
+	/*
